import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"API und Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"de/car-wash/api.md","filePath":"de/car-wash/api.md"}'),c={name:"de/car-wash/api.md"};function i(r,e,n,s,h,l){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="api-und-webhooks" tabindex="-1">API und Webhooks <a class="header-anchor" href="#api-und-webhooks" aria-label="Permalink to &quot;API und Webhooks&quot;">​</a></h1><h2 id="berechtigungen" tabindex="-1">Berechtigungen <a class="header-anchor" href="#berechtigungen" aria-label="Permalink to &quot;Berechtigungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Gewährt</th></tr></thead><tbody><tr><td><code>nay_car_wash.config</code></td><td><code>/nay:carwash</code> (Editor für Waschstraßen) und die Car Wash Einstellungen in <code>/nay</code>.</td></tr></tbody></table><p>Vergib ihn per ACE oder Regel, siehe <a href="/de/nay-lib/permissions">Berechtigungen</a>.</p><h2 id="http-api" tabindex="-1">HTTP-API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP-API&quot;">​</a></h2><p>Aktiviere zuerst die API und erstelle ein Token, siehe <a href="/de/nay-lib/api">HTTP-API</a>. Die Routen antworten mit <code>{ &quot;ok&quot;: true, &quot;data&quot;: ... }</code> und brauchen <code>Authorization: Bearer &lt;token&gt;</code>.</p><table tabindex="0"><thead><tr><th>Methode</th><th>Route</th><th>Scope</th><th>Query</th><th>Daten</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_car_wash/v1/history</code></td><td><code>nay_car_wash.history.read</code></td><td><code>identifier</code>, <code>kind</code> (<code>tunnel</code> oder <code>manual</code>), <code>limit</code> (1 bis 100, Standard 20), <code>before</code> (ID)</td><td><code>items</code> (<code>id</code>, <code>identifier</code>, <code>kind</code>, <code>location</code>, <code>program</code>, <code>price</code>, <code>time</code>), neueste zuerst, und <code>next</code>: Übergib es als <code>before</code> für die nächste Seite.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/stats</code></td><td><code>nay_car_wash.stats.read</code></td><td><code>days</code> (1 bis 31, Standard 7), <code>utcOffset</code> (Minuten, -720 bis 840, Standard: die Serveruhr)</td><td>Verwendeter <code>utcOffset</code>, <code>total</code>, <code>byDay</code> (jeder Tag aufgeführt) und <code>byLocation</code>, jeweils mit <code>washes</code> und <code>revenue</code>.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/tunnels</code></td><td><code>nay_car_wash.tunnels.read</code></td><td></td><td><code>index</code>, <code>label</code>, <code>enabled</code>, <code>entry</code> für jede Waschstraße.</td></tr></tbody></table><p>Beispiel:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nay_1_xxxxxxxx&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.example.com/nay_car_wash/v1/stats?days=7&quot;</span></span></code></pre></div><h2 id="webhook-ereignisse" tabindex="-1">Webhook-Ereignisse <a class="header-anchor" href="#webhook-ereignisse" aria-label="Permalink to &quot;Webhook-Ereignisse&quot;">​</a></h2><p>Wähle sie im Tab <strong>Webhooks</strong> von <code>/nay</code> aus, siehe <a href="/de/nay-lib/webhooks">Webhooks</a>.</p><table tabindex="0"><thead><tr><th>Ereignis</th><th>Wann</th><th>Daten</th></tr></thead><tbody><tr><td><code>nay_car_wash.wash</code></td><td>Eine Wäsche in der Waschstraße ist abgeschlossen.</td><td><code>player</code> (Name), <code>identifier</code>, <code>tunnel</code>, <code>program</code>, <code>price</code></td></tr><tr><td><code>nay_car_wash.manual</code></td><td>Eine Sitzung am Hochdruckreiniger endet.</td><td><code>player</code> (Name), <code>identifier</code>, <code>station</code>, <code>price</code></td></tr></tbody></table><p>Mit einem Discord-Webhook wird jede Wäsche zu einem Embed in deinem Kanal, in der Serversprache.</p>',13)])])}const b=t(c,[["render",i]]);export{p as __pageData,b as default};
